alter table public.rejchat_chat_reactions drop constraint rejchat_chat_reactions_emoji_check;
alter table public.rejchat_dm_reactions drop constraint rejchat_dm_reactions_emoji_check;
alter table public.rejchat_chat_reactions add constraint rejchat_chat_reactions_emoji_fk foreign key (emoji) references public.rejchat_reaction_emojis(emoji);
